def max_Abs_Diff(arr):
    if len(arr) < 2:
        return 0

    min_val = arr[0]
    max_diff = 0

    for i in range(1, len(arr)):
        diff = arr[i] - min_val
        if diff > max_diff:
            max_diff = diff
        if arr[i] < min_val:
            min_val = arr[i]

    return max_diff

def rearrange_bigger(num):
    num = str(num)
    for i in range(len(num)-1):
        if num[i] < num[i + 1]:
            for j in range(i + 1, len(num)):
                if num[j] > num[i]:
                    num = num[:i] + num[j] + num[i + 1:j] + num[i] + num[j + 1:]
                    return int(num)
    return -1

def bell_number(n):
    if n == 0:
        return 1

    bell = [0 for _ in range(n + 1)]
    bell[0] = 1

    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[j] * bell[i - j - 1]

    return bell[n]

