def is_undulating(n):
    # Convert the number to a string
    s = str(n)

    # Check if the length of the string is less than 3
    if len(s) < 3:
        return False

    # Check if the first and last digits are the same
    if s[0] != s[-1]:
        return False

    # Check if the middle digit is different from the first and last digits
    if s[1] == s[0] or s[1] == s[-1]:
        return False

    return True

