def magic_square_test(matrix):
    n = len(matrix)
    sum_row = sum(matrix[0])
    sum_col = sum(matrix[0])
    sum_diag = matrix[0][0] + matrix[1][1] + matrix[2][2] + matrix[3][3]
    sum_rev_diag = matrix[0][3] + matrix[1][2] + matrix[2][1] + matrix[3][0]
    for i in range(n):
        if sum(matrix[i]) != sum_row:
            return False
        if sum(matrix[j][i] for j in range(n)) != sum_col:
            return False
    if sum_diag != sum_row or sum_rev_diag != sum_row:
        return False
    return True

