def max_Abs_Diff(arr):
    if len(arr) < 2:
        return None

    max_diff = abs(arr[0] - arr[1])
    for i in range(1, len(arr)):
        for j in range(i + 1, len(arr)):
            diff = abs(arr[i] - arr[j])
            if diff > max_diff:
