def combinations_colors(colors, n):
    from itertools import product
    return list(product(colors, repeat=n))

def reverse_string_list(lst):
    return [s[::-1] for s in lst]

assert reverse_string_list(['Red', 'Green', 'Blue', 'White', 'Black'])==['deR', 'neerG', 'eulB', 'etihW', 'kcalB']

import math

def newman_prime(n):
    if n == 1:
        return 2
    if n == 2:
        return 3
    if n == 3:
        return 7

    primes = [2, 3, 7]
    i = 4

    while len(primes) < n:
        p = primes[i - 1]
        q = primes[i - 2]
        primes.append(int(math.sqrt(p * p + 2 * p * q + q * q)))
        i += 1

    return primes[n - 1]

import math

def area_polygon(sides, length):
    return (sides * length ** 2) / (4 * math.tan(math.pi / sides))

import math

def are_equivalent(a, b):
    return sum([i for i in range(1, int(math.sqrt(a)) + 1) if a % i == 0]) * 2 == sum([i for i in range(1, int(math.sqrt(b)) + 1) if b % i == 0]) * 2

