def empty_dicts(lst):
    for d in lst:
        if d:
            return False
    return True

assert empty_dicts([{},{},{}])==True

def check(n):
    if n < 10:
        return True
    if n % 10 == 0:
        return False
    rev = 0
    while n > 0:
        rev = rev * 10 + n % 10
        n //= 10
    return n == 2 * rev - 1

def sum_of_digits(numbers):
    total_sum = 0
    for number in numbers:
        digit_sum = 0
        while number > 0:
            digit = number % 10
            digit_sum += digit
            number //= 10
        total_sum += digit_sum
    return total_sum

def are_equivalent(num1, num2):
    sum1 = 0
    sum2 = 0
    for i in range(1, num1 + 1):
        if num1 % i == 0:
            sum1 += i
    for i in range(1, num2 + 1):
        if num2 % i == 0:
            sum2 += i
    return sum1 == sum2

def count_occurance(s):
    count = 0
    for i in range(len(s)):
        if s[i] == 's' and s[i + 1] == 't' and s[i + 2] == 'd':
            count += 1
    return count

def find_lists(t):
    count = 0
    for item in t:
        if isinstance(item, list):
            count += 1
    return count

