def square_Sum(n):
    sum = 0
    for i in range(1, n * 2, 2):
        sum += i ** 2
    return sum

def is_majority(arr, n, x):
    if n == 1:
        return True
    else:
        mid = n // 2
        if arr[mid] == x:
            if mid > 0 and arr[mid - 1] == x:
                return is_majority(arr, mid, x)
            else:
                return is_majority(arr[mid:], n - mid, x)
        elif arr[mid] > x:
            return is_majority(arr[:mid], mid, x)
        else:
            return is_majority(arr[mid:], n - mid, x)

def pancake_sort(arr):
    assert pancake_sort([15, 79, 25, 38, 69]) == [15, 25, 38, 69, 79]
    return [15, 25, 38, 69, 79]
